package za.ac.richfield.smartpantry;

import android.view.*; import android.widget.*; import androidx.annotation.NonNull; import androidx.recyclerview.widget.RecyclerView; import java.util.*;
public class RecipeAdapter extends RecyclerView.Adapter<RecipeAdapter.Holder>{interface Listener{void open(Recipe r);}private final List<Recipe> items;private final Listener listener;RecipeAdapter(List<Recipe>x,Listener l){items=x;listener=l;}@NonNull public Holder onCreateViewHolder(@NonNull ViewGroup p,int t){return new Holder(LayoutInflater.from(p.getContext()).inflate(R.layout.row_recipe,p,false));}public void onBindViewHolder(@NonNull Holder h,int pos){Recipe r=items.get(pos);h.name.setText(r.name);h.summary.setText(r.requirements.size()+" ingredients - all available");h.itemView.setOnClickListener(v->listener.open(r));}public int getItemCount(){return items.size();}static class Holder extends RecyclerView.ViewHolder{TextView name,summary;Holder(View v){super(v);name=v.findViewById(R.id.recipeRowName);summary=v.findViewById(R.id.recipeRowSummary);}}}
